/**
 * The QUFI mark, inlined.
 *
 * Base64 rather than a file import so the Next build and the single-file
 * esbuild bundle resolve it identically — Next hands back a StaticImageData
 * object for an image import, esbuild hands back a string, and the logo has to
 * work the same way in both.
 */
export const QUFI_MARK = 'data:image/png;base64,';
